ops.text:
/* 1.0.1: el estado va en una insignia sobre la esquina, así no pisa el nombre */
.mp-n__insignia circle { fill: var(--gds-color-bg); stroke: var(--gds-color-border-default); stroke-width: 1.5px; }
.mp-e--ok .mp-n__insignia circle     { stroke: var(--gds-color-border-success); }
.mp-e--espera .mp-n__insignia circle { stroke: var(--gds-color-border-warning); }
.mp-e--alerta .mp-n__insignia circle { stroke: var(--gds-color-border-danger); }
.mp-e--pausa .mp-n__insignia circle  { stroke: var(--gds-color-border-control); }
.mp-n__estado { font-size: 11px; font-weight: 700; fill: var(--gds-color-text-muted); }
.mp-n--auto .mp-n__estado { font-size: 9px; }
